/**
 * Lecture robuste du contexte (ADR-0024 §5.3-5.4) : une ligne au lieu des
 * gardes manuelles, y compris quand le harness ne fournit pas `params`.
 */
import type { OnirtechContext, TemplateCapability } from "./types.js";
/** Lit un paramètre scalaire dans `ctx.params`, sinon retourne `fallback`. */
export declare function param<T extends string | number | boolean>(ctx: OnirtechContext, key: string, fallback: T): T | string | number | boolean;
/** Indique si le template a déclaré (et reçu) la capacité demandée. */
export declare function hasCapability(ctx: OnirtechContext, capability: TemplateCapability): boolean;
